fn all_characters_same(s: &[u8]) -> bool {
    // An empty slice or a single‐element slice trivially has all identical bytes.
    if let Some((&first, rest)) = s.split_first() {
        // Check that every subsequent byte equals the first one.
        rest.iter().all(|&b| b == first)
    } else {
        true
    }
}

